import fs from 'fs/promises';
import path from 'path';

const DB_PATH = path.join(process.cwd(), 'app/notifications.json');

export async function getNotificationPreference(): Promise<boolean> {
  try {
    const data = await fs.readFile(DB_PATH, 'utf-8');
    return JSON.parse(data).notificationsEnabled;
  } catch (error) {
    // If file doesn't exist or error, default to false
    return false;
  }
}

export async function toggleNotificationPreference() {
  const current = await getNotificationPreference();
  const newState = !current;
  await fs.writeFile(DB_PATH, JSON.stringify({ notificationsEnabled: newState }, null, 2));
  return newState;
}

'use server';

import { revalidatePath } from 'next/cache';
import { toggleNotificationPreference } from './data';

export async function toggleNotifications() {
  await toggleNotificationPreference();
  revalidatePath('/');
}

import { getNotificationPreference } from './data';
import { toggleNotifications } from './actions';

export default async function Home() {
  const notificationsEnabled = await getNotificationPreference();

  return (
    <main className="p-4">
      <h1 className="text-2xl font-bold mb-4">Settings</h1>

      <div className="border p-4 rounded-lg shadow-sm max-w-md">
        <div className="flex items-center justify-between mb-4">
          <span className="font-medium">Notification Preference</span>
          <span className={`px-2 py-1 rounded text-sm ${notificationsEnabled ? 'bg-green-100 text-green-800' : 'bg-gray-100 text-gray-800'}`}>
            {notificationsEnabled ? 'On' : 'Off'}
          </span>
        </div>

        <form action={toggleNotifications}>
          <button 
            type="submit" 
            className="w-full bg-blue-500 hover:bg-blue-600 text-white font-bold py-2 px-4 rounded transition-colors"
          >
            Toggle Notifications
          </button>
        </form>

        <p className="mt-4 text-sm text-gray-500">
          This page uses <code>revalidatePath('/')</code> to refresh the content after the server action completes.
        </p>
      </div>
    </main>
  );
}

export const metadata = {
  title: 'Notification Settings',
  description: 'Manage your notification preferences',
};

export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  );
}

import { expect, test, vi, beforeEach } from 'vitest';
import { toggleNotifications } from './actions';
import { getNotificationPreference } from './data';
import fs from 'fs/promises';
import path from 'path';

// Mock next/cache
vi.mock('next/cache', () => ({
  revalidatePath: vi.fn(),
}));

const DB_PATH = path.join(process.cwd(), 'app/notifications.json');

// Reset the file before each test
beforeEach(async () => {
  await fs.writeFile(DB_PATH, JSON.stringify({ notificationsEnabled: false }));
});

test('toggles notifications and revalidates path', async () => {
  const { revalidatePath } = await import('next/cache');

  // Initial state check
  expect(await getNotificationPreference()).toBe(false);

  // Toggle
  await toggleNotifications();

  // Check state changed
  expect(await getNotificationPreference()).toBe(true);

  // Check revalidatePath was called
  expect(revalidatePath).toHaveBeenCalledWith('/');

  // Toggle back
  await toggleNotifications();
  expect(await getNotificationPreference()).toBe(false);
});
